        x = torch.randn(B, T, D_MODEL)
        attn.train()
        out_train_a = attn(x)
        out_train_b = attn(x)
        attn.eval()
        out_eval_a = attn(x)
        out_eval_b = attn(x)
        self.assertFalse(torch.allclose(out_train_a, out_train_b))
